import{_ as t,o as a,c as s,a3 as o}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Meta App Setup for EloSync / EloSync","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Meta App Setup for EloSync / EloSync | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/meta-app-setup"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Meta App Setup for EloSync / EloSync | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/meta-app-setup"}]]},"headers":[],"relativePath":"developer-guide/meta-app-setup.md","filePath":"developer-guide/meta-app-setup.md","lastUpdated":1786199211000}'),i={name:"developer-guide/meta-app-setup.md"};function n(r,e,l,d,p,c){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="meta-app-setup-for-elosync-elosync" tabindex="-1">Meta App Setup for EloSync / EloSync <a class="header-anchor" href="#meta-app-setup-for-elosync-elosync" aria-label="Permalink to &quot;Meta App Setup for EloSync / EloSync&quot;">​</a></h1><blockquote><p><strong>Operator guide</strong> — how to create a Meta (Facebook) Developer App and wire it to the platform so tenants can connect <strong>Meta Lead Ads</strong>.</p><p>Architecture and driver details: <a href="/developer-guide/meta-lead-ads-integration">Meta Lead Ads Integration</a>.<br> Production gates: <a href="/deployment/leads">Leads — Production Guide</a>.</p></blockquote><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>EloSync uses <strong>one platform Meta App</strong> (Central credentials). Each tenant then connects their own Facebook Pages via OAuth. Page tokens stay tenant-scoped; webhooks share a single ingress URL.</p><table tabindex="0"><thead><tr><th>Role</th><th>Example host</th><th>Purpose</th></tr></thead><tbody><tr><td>API (<code>APP_URL</code>)</td><td><code>https://api.elosync.com</code></td><td>OAuth callback + webhook</td></tr><tr><td>SPA (<code>FRONTEND_URL</code>)</td><td><code>https://app.elosync.com</code></td><td>Post-OAuth return to Leads UI</td></tr></tbody></table><p>Replace hosts with your real <code>APP_URL</code> / <code>FRONTEND_URL</code>.</p><h3 id="two-different-meta-urls-do-not-mix" tabindex="-1">Two different Meta URLs (do not mix) <a class="header-anchor" href="#two-different-meta-urls-do-not-mix" aria-label="Permalink to &quot;Two different Meta URLs (do not mix)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Purpose</th><th>Path</th><th>Where to register in Meta</th></tr></thead><tbody><tr><td><strong>OAuth redirect</strong></td><td><code>https://{api}/api/oauth/leads/meta/callback</code></td><td>Facebook Login for Business → <strong>Valid OAuth Redirect URIs</strong></td></tr><tr><td><strong>Webhook callback</strong></td><td><code>https://{api}/webhooks/leads/meta</code></td><td>Webhooks → Callback URL (<code>leadgen</code>)</td></tr></tbody></table><p>Putting the webhook URL in Valid OAuth Redirect URIs causes <strong>URL blocked</strong>. Putting only the OAuth URL in Webhooks breaks lead delivery.</p><hr><h2 id="part-a-—-create-the-meta-app" tabindex="-1">Part A — Create the Meta App <a class="header-anchor" href="#part-a-—-create-the-meta-app" aria-label="Permalink to &quot;Part A — Create the Meta App&quot;">​</a></h2><h3 id="_1-create-the-app" tabindex="-1">1. Create the app <a class="header-anchor" href="#_1-create-the-app" aria-label="Permalink to &quot;1. Create the app&quot;">​</a></h3><ol><li>Open <a href="https://developers.facebook.com/" target="_blank" rel="noreferrer">Meta for Developers</a> → <strong>My Apps</strong> → <strong>Create App</strong>.</li><li>When asked for a use case, select <strong>Create &amp; manage ads with Marketing API</strong>.</li><li>If a follow-up offers <strong>Capture &amp; manage ad leads</strong> (or similar), enable it.</li><li>Name the app (e.g. <code>EloSync</code>), set a contact email, attach a Business Portfolio if prompted.</li><li>Finish creation.</li></ol><p>Do <strong>not</strong> rely on <strong>Authenticate and request data from users with Facebook Login</strong> alone — that does not unlock Lead Ads scopes (<code>leads_retrieval</code>, etc.).</p><h3 id="_2-app-domains" tabindex="-1">2. App Domains <a class="header-anchor" href="#_2-app-domains" aria-label="Permalink to &quot;2. App Domains&quot;">​</a></h3><p><strong>App settings → Basic → App domains</strong> (bare hosts, no <code>https://</code>):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>elosync.com</span></span>
<span class="line"><span>api.elosync.com</span></span>
<span class="line"><span>app.elosync.com</span></span></code></pre></div><p>Add every SPA subdomain you actually use. Missing domains cause: <em>The domain of this URL isn&#39;t included in the app&#39;s domains.</em></p><p>Save changes.</p><h3 id="_3-enable-permissions-required" tabindex="-1">3. Enable permissions (required) <a class="header-anchor" href="#_3-enable-permissions-required" aria-label="Permalink to &quot;3. Enable permissions (required)&quot;">​</a></h3><p>EloSync requests these OAuth scopes (<code>config/meta.php</code>):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>leads_retrieval</span></span>
<span class="line"><span>pages_manage_metadata</span></span>
<span class="line"><span>pages_show_list</span></span>
<span class="line"><span>pages_read_engagement</span></span>
<span class="line"><span>business_management</span></span></code></pre></div><ol><li>Open <strong>Use cases</strong> → <strong>Create &amp; manage ads with Marketing API</strong> → <strong>Customize</strong>.</li><li>Under <strong>Permissions and features</strong>, add each permission above until status is <strong>Ready for testing</strong>.</li><li>Also enable if Meta lists them for Lead Ads: <code>pages_manage_ads</code>, <code>ads_management</code>, <code>ads_read</code>.</li></ol><p>If a scope is missing from the app, Facebook shows <strong>Invalid Scopes</strong> (developers only). Enabling permissions on the use case is the fix — not changing EloSync code.</p><h3 id="_4-facebook-login-for-business" tabindex="-1">4. Facebook Login for Business <a class="header-anchor" href="#_4-facebook-login-for-business" aria-label="Permalink to &quot;4. Facebook Login for Business&quot;">​</a></h3><p>Left nav → <strong>Facebook Login for Business</strong> → <strong>Settings</strong>:</p><ol><li><strong>Client OAuth login</strong> = Yes</li><li><strong>Web OAuth login</strong> = Yes</li><li><strong>Enforce HTTPS</strong> = Yes</li><li><strong>Valid OAuth Redirect URIs</strong> — add <strong>only</strong>:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://{api}/api/oauth/leads/meta/callback</span></span></code></pre></div><p>Example: <code>https://api.elosync.com/api/oauth/leads/meta/callback</code></p><ol start="5"><li>Save.</li><li>Use the <strong>Redirect URI Validator</strong> with that same callback URL (not the webhook path).</li></ol><h3 id="_5-webhooks" tabindex="-1">5. Webhooks <a class="header-anchor" href="#_5-webhooks" aria-label="Permalink to &quot;5. Webhooks&quot;">​</a></h3><p>Configure a Page webhook for leadgen:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Callback URL</td><td><code>https://{api}/webhooks/leads/meta</code></td></tr><tr><td>Verify token</td><td>Long random string (store securely; EloSync must use the same value)</td></tr><tr><td>Subscription</td><td><strong>Page</strong> → field <strong><code>leadgen</code></strong></td></tr></tbody></table><p>Verify and save <strong>after</strong> Central credentials are stored (Part B), or Meta’s verify challenge will fail.</p><h3 id="_6-copy-credentials" tabindex="-1">6. Copy credentials <a class="header-anchor" href="#_6-copy-credentials" aria-label="Permalink to &quot;6. Copy credentials&quot;">​</a></h3><p><strong>App settings → Basic</strong>:</p><ul><li><strong>App ID</strong></li><li><strong>App Secret</strong> (Show → copy)</li></ul><hr><h2 id="part-b-—-connect-meta-to-elosync-central" tabindex="-1">Part B — Connect Meta to EloSync (Central) <a class="header-anchor" href="#part-b-—-connect-meta-to-elosync-central" aria-label="Permalink to &quot;Part B — Connect Meta to EloSync (Central)&quot;">​</a></h2><h3 id="_1-backend-env" tabindex="-1">1. Backend env <a class="header-anchor" href="#_1-backend-env" aria-label="Permalink to &quot;1. Backend env&quot;">​</a></h3><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">APP_URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=https://api.elosync.com</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FRONTEND_URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=https://app.elosync.com</span></span></code></pre></div><p>Optional (instead of, or as fallback for, Central settings):</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">META_LEAD_ADS_APP_ID</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">META_LEAD_ADS_APP_SECRET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">META_LEAD_ADS_WEBHOOK_VERIFY_TOKEN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">META_GRAPH_VERSION</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=v21.0</span></span></code></pre></div><p><code>oauthRedirectUri()</code> and <code>webhookUrl()</code> are built from <code>url(...)</code> / <code>APP_URL</code>. A wrong <code>APP_URL</code> produces a redirect URI Meta will reject.</p><h3 id="_2-save-credentials-via-central-api" tabindex="-1">2. Save credentials via Central API <a class="header-anchor" href="#_2-save-credentials-via-central-api" aria-label="Permalink to &quot;2. Save credentials via Central API&quot;">​</a></h3><p>Authenticated Central admin:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PUT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/central/v1/integrations/meta-lead-ads</span></span></code></pre></div><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;meta_lead_ads_app_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;YOUR_APP_ID&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;meta_lead_ads_app_secret&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;YOUR_APP_SECRET&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;meta_lead_ads_webhook_verify_token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;YOUR_VERIFY_TOKEN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;meta_graph_version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;v21.0&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Confirm with <code>GET /api/central/v1/integrations/meta-lead-ads</code>:</p><ul><li><code>configured</code> = <code>true</code></li><li><code>oauth_redirect_uri</code> = <code>https://{api}/api/oauth/leads/meta/callback</code></li><li><code>webhook_url</code> = <code>https://{api}/webhooks/leads/meta</code></li></ul><h3 id="_3-queue-worker" tabindex="-1">3. Queue worker <a class="header-anchor" href="#_3-queue-worker" aria-label="Permalink to &quot;3. Queue worker&quot;">​</a></h3><p>Meta ingest uses the <code>lead-ingest</code> queue. At least one worker must listen to it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:work</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --queue=lead-ingest,imports,emails,default</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sleep=1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tries=3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --max-time=3600</span></span></code></pre></div><h3 id="_4-finish-meta-webhook-verification" tabindex="-1">4. Finish Meta webhook verification <a class="header-anchor" href="#_4-finish-meta-webhook-verification" aria-label="Permalink to &quot;4. Finish Meta webhook verification&quot;">​</a></h3><p>In Meta → Webhooks, <strong>Verify and save</strong> the callback + verify token now that EloSync can answer the challenge.</p><hr><h2 id="part-c-—-connect-a-tenant-workspace" tabindex="-1">Part C — Connect a tenant workspace <a class="header-anchor" href="#part-c-—-connect-a-tenant-workspace" aria-label="Permalink to &quot;Part C — Connect a tenant workspace&quot;">​</a></h2><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ul><li>Leads module installed for the workspace</li><li>User permission <code>leads.manage_integrations</code></li><li>While the Meta app is in <strong>Development</strong>, the Facebook user must be an <strong>Admin / Developer / Tester</strong> on the app</li><li>That user must be able to access the Facebook Page and Lead Forms to connect</li></ul><h3 id="steps-in-elosync" tabindex="-1">Steps in EloSync <a class="header-anchor" href="#steps-in-elosync" aria-label="Permalink to &quot;Steps in EloSync&quot;">​</a></h3><ol><li>Open the tenant app → <strong>Leads</strong>.</li><li>Open <strong>Integrations</strong> → tab <strong>Meta Lead Ads</strong>.</li><li>If the tab says platform is not configured, finish Part B first.</li><li>Click <strong>Connect Meta</strong> → approve Facebook permissions.</li><li>Select Facebook <strong>Page(s)</strong> to subscribe → save.</li><li>Status should become <strong>connected</strong>. Optional: set <strong>Default source</strong> label.</li></ol><h3 id="smoke-test" tabindex="-1">Smoke test <a class="header-anchor" href="#smoke-test" aria-label="Permalink to &quot;Smoke test&quot;">​</a></h3><ol><li>Submit a Lead Ad form on a subscribed Page.</li><li>Confirm a lead appears in that workspace.</li></ol><p>In Development mode, test submissions typically must come from users with a role on the Meta app.</p><hr><h2 id="part-d-—-production-customer-pages" tabindex="-1">Part D — Production (customer Pages) <a class="header-anchor" href="#part-d-—-production-customer-pages" aria-label="Permalink to &quot;Part D — Production (customer Pages)&quot;">​</a></h2><p>Before real customer Pages work outside app roles:</p><ol><li>Complete Meta <strong>Business Verification</strong>.</li><li>Submit <strong>App Review</strong> for <code>leads_retrieval</code>, <code>pages_manage_metadata</code>, and related Page scopes.</li><li>Switch the app to <strong>Live</strong>.</li><li>Re-smoke: Connect Meta → select Pages → form submit → lead created.</li></ol><p>Until steps 1–3 are done, only Meta test apps / app-role users work. See <a href="/deployment/leads">Leads — Production Guide</a>.</p><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Error / symptom</th><th>Likely cause</th><th>Fix</th></tr></thead><tbody><tr><td><strong>URL blocked</strong> / redirect not white-listed</td><td>Webhook URL registered as OAuth redirect, or <code>APP_URL</code> mismatch</td><td>Whitelist exact <code>/api/oauth/leads/meta/callback</code>; match scheme/host/port to <code>APP_URL</code></td></tr><tr><td><strong>Domain of this URL isn&#39;t included in the app&#39;s domains</strong></td><td>SPA or API host missing from App Domains</td><td>Add <code>api.*</code>, <code>app.*</code>, and root domain; save</td></tr><tr><td><strong>Invalid Scopes: leads_retrieval, …</strong></td><td>Marketing API / Lead Ads use case missing, or permissions not <strong>Ready for testing</strong></td><td>Customize use case → add all EloSync scopes</td></tr><tr><td>Meta Lead Ads <strong>not configured by the platform administrator</strong></td><td>Central / env credentials incomplete</td><td>Set App ID, secret, and verify token</td></tr><tr><td>Connect works, no leads</td><td>Webhook not verified, <code>leadgen</code> not subscribed, or no <code>lead-ingest</code> worker</td><td>Fix Webhooks + queue worker</td></tr><tr><td>Validator green but OAuth still fails</td><td>Validated the <strong>webhook</strong> URL instead of the <strong>OAuth callback</strong></td><td>Re-check with <code>/api/oauth/leads/meta/callback</code></td></tr></tbody></table><hr><h2 id="checklist" tabindex="-1">Checklist <a class="header-anchor" href="#checklist" aria-label="Permalink to &quot;Checklist&quot;">​</a></h2><ul><li>[ ] Use case: <strong>Create &amp; manage ads with Marketing API</strong> (+ Lead Ads if offered)</li><li>[ ] Permissions <strong>Ready for testing</strong> (all five EloSync scopes)</li><li>[ ] App Domains include API + SPA hosts</li><li>[ ] OAuth redirect = <code>/api/oauth/leads/meta/callback</code></li><li>[ ] Webhook = <code>/webhooks/leads/meta</code> + Page <code>leadgen</code></li><li>[ ] Central / <code>META_LEAD_ADS_*</code> configured; <code>GET</code> shows <code>configured: true</code></li><li>[ ] Queue worker includes <code>lead-ingest</code></li><li>[ ] Tenant Connect Meta → select Pages → test form</li></ul><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/developer-guide/meta-lead-ads-integration">Meta Lead Ads Integration</a> — architecture, driver, multi-tenant design</li><li><a href="/developer-guide/lead-source-driver-architecture">Lead Source Driver Architecture</a></li><li><a href="/developer-guide/custom-lead-webhook">Custom Lead Webhook</a></li><li><a href="/deployment/leads">Leads — Production Guide</a></li><li><a href="/user-guide/leads-overview">Leads — User Guide</a></li><li><a href="/api/tenant-v1-leads">Tenant Leads API</a></li><li><a href="/developer-guide/whatsapp-cloud-integration">WhatsApp Cloud Integration</a> — separate Meta products; may share a Business Portfolio later</li></ul>`,79)])])}const u=t(i,[["render",n]]);export{g as __pageData,u as default};
